// PKCS#12 key derivation as used by BouncyCastle's
// "PBEWithSHA256And256BitAES-CBC-BC" (SHA-256, 20 iterations, 8-byte salt).
// Spec: doc/crypto.md.

import {
  asBufferSource,
  concat,
  repeatTo,
  utf16beWithNullTerminator,
} from '../util/bytes';

/** Number of KDF iterations the Android app uses (PBEParameterSpec(_, 20)). */
export const KDF_ITERATIONS = 20;

/** SHA-256 input block size in bytes (the PKCS#12 `v` constant). */
const SHA256_BLOCK_SIZE = 64;

/** SHA-256 digest size in bytes (the PKCS#12 `u` constant). */
const SHA256_DIGEST_SIZE = 32;

/** Derive one PKCS#12 key block with WebCrypto's SHA-256. */
async function sha256(data: Uint8Array): Promise<Uint8Array> {
  return new Uint8Array(
    await crypto.subtle.digest('SHA-256', asBufferSource(data)),
  );
}

/**
 * Derive one 32-byte PKCS#12 key block for the diversifier `idByte`
 * (`1` = key, `2` = IV). Mirrors BouncyCastle's `PKCS12ParametersGenerator`.
 */
export async function pkcs12Block(
  idByte: number,
  password: string,
  salt: Uint8Array,
  iterations: number,
): Promise<Uint8Array> {
  const D = new Uint8Array(SHA256_BLOCK_SIZE).fill(idByte);
  const S = repeatTo(salt, SHA256_BLOCK_SIZE);
  const P = repeatTo(utf16beWithNullTerminator(password), SHA256_BLOCK_SIZE);
  const I = concat(S, P);

  let A = await sha256(concat(D, I));
  for (let i = 1; i < iterations; i++) {
    A = await sha256(A);
  }
  // A single SHA-256 block (32 bytes) is enough for both the key and the IV.
  return A.slice(0, SHA256_DIGEST_SIZE);
}

/** A 256-bit AES-CBC key plus its 16-byte IV, derived from a master password. */
export interface KeyAndIv {
  key: CryptoKey;
  iv: Uint8Array;
}

/**
 * Derive the AES-256-CBC key and 16-byte IV from a master password and the
 * 8-byte file salt (PKCS#12 KDF). The key is imported for `encrypt`/`decrypt`.
 */
export async function deriveKeyAndIv(
  password: string,
  salt: Uint8Array,
): Promise<KeyAndIv> {
  const keyBlock = await pkcs12Block(1, password, salt, KDF_ITERATIONS);
  const ivBlock = await pkcs12Block(2, password, salt, KDF_ITERATIONS);
  const key = await crypto.subtle.importKey(
    'raw',
    keyBlock.slice(0, 32),
    { name: 'AES-CBC' },
    false,
    ['encrypt', 'decrypt'],
  );
  return { key, iv: ivBlock.slice(0, 16) };
}
